import React,{useEffect,useMemo,useState}from"react";import{CalendarDays,Clock,Save,Trash2}from"lucide-react";import AppShell from"../../components/AppShell";import{getVeterinarians,todayLocal}from"../../services/appointmentService";import{DAYS,getAllSchedules,getScheduleOverrides,saveWeeklySchedule,saveScheduleOverride,deleteScheduleOverride}from"../../services/scheduleService";
const blankWeekly={veterinarianId:"",dayOfWeek:1,startTime:"09:00",endTime:"19:00",isAvailable:true};const blankOverride={veterinarianId:"",scheduleDate:"",startTime:"09:00",endTime:"19:00",isAvailable:true,reason:""};
export default function VeterinarianScheduleManagement({profile}){const[vets,setVets]=useState([]),[weekly,setWeekly]=useState([]),[overrides,setOverrides]=useState([]),[wf,setWf]=useState(blankWeekly),[of,setOf]=useState(blankOverride),[message,setMessage]=useState(""),[loading,setLoading]=useState(true);async function load(){setLoading(true);try{const[v,s,o]=await Promise.all([getVeterinarians(),getAllSchedules(),getScheduleOverrides()]);setVets(v);setWeekly(s);setOverrides(o)}catch(e){setMessage(e.message)}finally{setLoading(false)}}useEffect(()=>{load()},[]);const grouped=useMemo(()=>vets.map(v=>({vet:v,rows:DAYS.map((d,i)=>weekly.find(x=>x.veterinarian_id===v.id&&x.day_of_week===i)||{day_of_week:i,is_available:false})})),[vets,weekly]);async function submitWeekly(e){e.preventDefault();try{await saveWeeklySchedule(wf);setMessage("Weekly schedule saved.");await load()}catch(e){setMessage(e.message)}}async function submitOverride(e){e.preventDefault();try{await saveScheduleOverride({...of,createdBy:profile.id});setMessage("Date schedule saved. Booking slots will follow this date-specific schedule.");setOf(blankOverride);await load()}catch(e){setMessage(e.message)}}return <AppShell profile={profile} title="Veterinarian Schedule Management"><div className="schedule-grid"><form className="card" onSubmit={submitWeekly}><h2><Clock/> Weekly Schedule</h2><label>Veterinarian<select required value={wf.veterinarianId} onChange={e=>setWf({...wf,veterinarianId:e.target.value})}><option value="">Select veterinarian</option>{vets.map(v=><option key={v.id} value={v.id}>{v.full_name}</option>)}</select></label><label>Day<select value={wf.dayOfWeek} onChange={e=>setWf({...wf,dayOfWeek:e.target.value})}>{DAYS.map((d,i)=><option value={i} key={d}>{d}</option>)}</select></label><div className="two"><label>Start Time<input type="time" value={wf.startTime} onChange={e=>setWf({...wf,startTime:e.target.value})} disabled={!wf.isAvailable}/></label><label>End Time<input type="time" value={wf.endTime} onChange={e=>setWf({...wf,endTime:e.target.value})} disabled={!wf.isAvailable}/></label></div><label className="check"><input type="checkbox" checked={wf.isAvailable} onChange={e=>setWf({...wf,isAvailable:e.target.checked})}/> Veterinarian is available</label><button><Save size={17}/> Save Weekly Schedule</button></form><form className="card" onSubmit={submitOverride}><h2><CalendarDays/> Specific Date / Leave</h2><label>Veterinarian<select required value={of.veterinarianId} onChange={e=>setOf({...of,veterinarianId:e.target.value})}><option value="">Select veterinarian</option>{vets.map(v=><option key={v.id} value={v.id}>{v.full_name}</option>)}</select></label><label>Schedule Date<input required min={todayLocal()} type="date" value={of.scheduleDate} onChange={e=>setOf({...of,scheduleDate:e.target.value})}/></label><label className="check"><input type="checkbox" checked={of.isAvailable} onChange={e=>setOf({...of,isAvailable:e.target.checked})}/> Available on this date</label>{of.isAvailable&&<div className="two"><label>Start Time<input type="time" required value={of.startTime} onChange={e=>setOf({...of,startTime:e.target.value})}/></label><label>End Time<input type="time" required value={of.endTime} onChange={e=>setOf({...of,endTime:e.target.value})}/></label></div>}<label>Reason / Note<input value={of.reason} onChange={e=>setOf({...of,reason:e.target.value})} placeholder="Leave, seminar, adjusted hours..."/></label><button><Save size={17}/> Save Date Schedule</button></form></div>{message&&<div className="notice">{message}</div>}<div className="card table-card"><h2>Current Weekly Schedules</h2>{loading?<p>Loading...</p>:grouped.map(g=><div className="vet-block" key={g.vet.id}><h3>{g.vet.full_name}</h3><div className="day-grid">{g.rows.map(r=><div className={r.is_available?"day":"day off"} key={r.day_of_week}><strong>{DAYS[r.day_of_week]}</strong><span>{r.is_available?`${String(r.start_time).slice(0,5)} – ${String(r.end_time).slice(0,5)}`:"Unavailable"}</span></div>)}</div></div>)}</div><div className="card table-card"><h2>Date-specific Schedules</h2>{overrides.length===0?<p>No date-specific schedules yet.</p>:<div className="responsive"><table><thead><tr><th>Date</th><th>Veterinarian</th><th>Availability</th><th>Reason</th><th></th></tr></thead><tbody>{overrides.map(o=><tr key={o.id}><td>{o.schedule_date}</td><td>{o.veterinarian?.full_name}</td><td>{o.is_available?`${String(o.start_time).slice(0,5)} – ${String(o.end_time).slice(0,5)}`:"Unavailable / Leave"}</td><td>{o.reason||"—"}</td><td><button className="danger" onClick={async()=>{await deleteScheduleOverride(o.id);load()}}><Trash2 size={15}/></button></td></tr>)}</tbody></table></div>}</div><style>{`.schedule-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-bottom:18px}.card h2{display:flex;align-items:center;gap:8px;margin-top:0}.card label{display:grid;gap:6px;font-weight:700;font-size:13px;margin-bottom:13px}.card input,.card select{padding:11px;border:1px solid #cfe4ed;border-radius:10px}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.check{display:flex!important;grid-template-columns:auto 1fr!important;align-items:center;font-weight:600!important}.check input{width:auto}.card>button{border:0;background:#4DA8DA;color:white;padding:12px 15px;border-radius:11px;font-weight:800;display:flex;gap:7px;align-items:center}.notice{padding:12px 15px;background:#eaf8ef;color:#28774b;border-radius:12px;margin-bottom:18px}.table-card{margin-bottom:18px}.vet-block{border-top:1px solid #e7f1f5;padding-top:12px;margin-top:12px}.day-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:8px}.day{background:#edf9fd;padding:10px;border-radius:10px;display:grid;gap:4px;font-size:12px}.day.off{background:#f4f6f7;color:#84939a}.responsive{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px;border-bottom:1px solid #e7f0f3}.danger{background:#fff0f0!important;color:#c84f4f!important;padding:8px!important}@media(max-width:900px){.schedule-grid{grid-template-columns:1fr}.day-grid{grid-template-columns:repeat(2,1fr)}}`}</style></AppShell>}
